import json
from lfx.custom.custom_component.component import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.data import Data

class MasterConfigParser(Component):
    display_name = "Master Config Parser"
    description = "Paste your raw JSON here. This node translates it into a Master Dictionary for all other tools to use."
    icon = "settings"
    name = "MasterConfigParser"

    inputs = [
        MessageTextInput(
            name="raw_json_text",
            display_name="System Config (Text)",
            info="Paste your full, raw JSON configuration here.",
            value="",
            tool_mode=False,
        ),
    ]

    outputs = [
        Output(display_name="Master Config (Data)", name="master_config", method="build_output"),
    ]

    def build_output(self) -> Data:
        raw_text = self.raw_json_text

        if not raw_text or not raw_text.strip():
            return Data(data={"error": "Input text is empty."})

        try:
            # Translates the raw text into a Python dictionary ONCE
            config = json.loads(raw_text)

            # Outputs the dictionary wrapped in a Data object for the wire
            return Data(data=config)

        except json.JSONDecodeError as e:
            return Data(data={"error": f"Invalid JSON format. Details: {str(e)}"})
